  const speakNext=()=>{if(speechIndex.current>=speechChunks.current.length){setAudioState("idle");return}const part=speechChunks.current[speechIndex.current++],utterance=new SpeechSynthesisUtterance(part.text);utterance.lang=lang==="zh"?"zh-CN":lang==="fr"?"fr-FR":"en-US";utterance.rate=audioRate;utterance.pitch=lang==="zh"?.96:.98;utterance.volume=.94;const voice=preferredVoice(utterance.lang);if(voice)utterance.voice=voice;utterance.onend=()=>setTimeout(speakNext,part.pause);utterance.onerror=()=>setAudioState("idle");speechSynthesis.speak(utterance)};
