export default function App(){
  if(location.pathname.startsWith("/admin"))return <Admin/>;
  const[tab,setTab]=useState("discover"),[open,setOpen]=useState(null),[openArchive,setOpenArchive]=useState(null),[subscribed,setSubscribed]=useState(false),[subscriptionPlan,setSubscriptionPlan]=useState(()=>readLocal("xart-subscription-plan","")||""),[items,setItems]=useState(fallbackItems),[archives,setArchives]=useState([]),[lang,setLang]=useState(()=>readLocal("xart-language","zh")||"zh"),[authenticated,setAuthenticated]=useState(()=>readLocal("xart-auth-complete")==="1"),[showSplash,setShowSplash]=useState(true);
  useEffect(()=>{const params=new URLSearchParams(location.search),arrivedFromAuth=params.get("from")==="auth",client=getAuthClient();let cancelled=false,resolved=false;const syncAuthState=hasSession=>{if(cancelled)return;setAuthenticated(hasSession);try{if(hasSession)localStorage.setItem("xart-auth-complete","1");else{localStorage.removeItem("xart-auth-complete");localStorage.removeItem("xart-stripe-session");localStorage.removeItem("xart-subscription-plan")}}catch{}if(!hasSession){setSubscribed(false);setSubscriptionPlan("");setOpenArchive(null)}};const resolveAuth=async()=>{let hasSession=false;try{if(client){const result=await Promise.race([client.auth.getSession(),new Promise(resolve=>setTimeout(()=>resolve({data:{session:null}}),2200))]);hasSession=Boolean(result?.data?.session)}else hasSession=readLocal("xart-auth-complete")==="1"}catch{}if(cancelled)return;resolved=true;syncAuthState(hasSession);setShowSplash(false);if(hasSession){if(arrivedFromAuth)history.replaceState({},"","/")}else if(!location.pathname.startsWith("/auth")){location.replace("/auth.html?next=/")}};const timer=setTimeout(resolveAuth,4600);const subscription=client?.auth?.onAuthStateChange?.((event,session)=>{if(event==="SIGNED_IN")syncAuthState(Boolean(session));if(event==="SIGNED_OUT"){syncAuthState(false);if(resolved&&document.visibilityState==="visible"&&!location.pathname.startsWith("/auth"))location.replace("/auth.html?next=/")}});return()=>{cancelled=true;clearTimeout(timer);subscription?.data?.subscription?.unsubscribe?.()}},[]);
  useEffect(()=>{writeLocal("xart-language",lang);document.documentElement.lang=lang==="zh"?"zh-CN":lang},[lang]);
  useEffect(()=>{
    let active=true;
    const syncArticles=()=>fetch(`/api/articles?t=${Date.now()}`,{cache:"no-store"}).then(r=>r.ok?r.json():Promise.reject()).then(data=>{if(active&&data.articles?.length)setItems(data.articles.map(p=>({id:p.id,n:p.n,tag:p.tag,minutes:p.minutes,locked:p.locked,language:p.language||"all",cover_image:p.cover_image||"",has_pdf:Boolean(p.has_pdf),pdf_name:p.pdf_name||"",pdf_size:Number(p.pdf_size)||0,audio_generated:Boolean(p.audio_generated),zh:[p.zh_title,p.zh_summary],fr:[p.fr_title,p.fr_summary],en:[p.en_title,p.en_summary],content:{zh:p.zh_content,fr:p.fr_content,en:p.en_content}})))}).catch(()=>{});
    const resume=()=>{if(document.visibilityState==="visible")syncArticles()};
    syncArticles();
    document.addEventListener("visibilitychange",resume);
    window.addEventListener("focus",syncArticles);
    window.addEventListener("pageshow",syncArticles);
    window.addEventListener("online",syncArticles);
    const timer=setInterval(()=>{if(document.visibilityState==="visible")syncArticles()},60000);
    return()=>{active=false;clearInterval(timer);document.removeEventListener("visibilitychange",resume);window.removeEventListener("focus",syncArticles);window.removeEventListener("pageshow",syncArticles);window.removeEventListener("online",syncArticles)};
  },[]);
  useEffect(()=>{
    let active=true;
    const syncArchives=()=>fetch(`/api/archives?t=${Date.now()}`,{cache:"no-store"}).then(r=>r.ok?r.json():Promise.reject()).then(data=>{if(active&&Array.isArray(data.archives))setArchives(data.archives)}).catch(()=>{});
    syncArchives();
    window.addEventListener("focus",syncArchives);
    window.addEventListener("pageshow",syncArchives);
    window.addEventListener("online",syncArchives);
    return()=>{active=false;window.removeEventListener("focus",syncArchives);window.removeEventListener("pageshow",syncArchives);window.removeEventListener("online",syncArchives)};
  },[]);
  useEffect(()=>{
    let checking=false;
    const checkVersion=async()=>{if(checking||document.visibilityState!=="visible")return;checking=true;try{const response=await fetch(`/?app-version=${Date.now()}`,{cache:"no-store",headers:{"cache-control":"no-cache"}});if(!response.ok)return;const html=await response.text(),parsed=new DOMParser().parseFromString(html,"text/html"),latest=parsed.querySelector('script[type="module"][src]')?.getAttribute("src"),current=document.querySelector('script[type="module"][src]')?.getAttribute("src");if(latest&&current&&latest!==current){const next=new URL(location.href);next.searchParams.set("app-update",Date.now());location.replace(next.href)}}catch{}finally{checking=false}};
    const resume=()=>{if(document.visibilityState==="visible")checkVersion()};
    document.addEventListener("visibilitychange",resume);
    window.addEventListener("focus",checkVersion);
    window.addEventListener("pageshow",checkVersion);
    window.addEventListener("online",checkVersion);
    const timer=setInterval(checkVersion,300000);
    checkVersion();
    return()=>{clearInterval(timer);document.removeEventListener("visibilitychange",resume);window.removeEventListener("focus",checkVersion);window.removeEventListener("pageshow",checkVersion);window.removeEventListener("online",checkVersion)};
  },[]);
  useEffect(()=>{const params=new URLSearchParams(location.search),sessionId=params.get("session_id")||localStorage.getItem("xart-stripe-session");if(params.get("checkout")==="cancelled")history.replaceState({},"",location.pathname);if(!sessionId)return;fetch(`/api/verify-checkout-session?session_id=${encodeURIComponent(sessionId)}&t=${Date.now()}`,{cache:"no-store"}).then(r=>r.json()).then(data=>{if(data.active){const plan=String(data.plan||"");setSubscribed(true);setSubscriptionPlan(plan);localStorage.setItem("xart-stripe-session",sessionId);localStorage.setItem("xart-subscription-plan",plan)}else{setSubscribed(false);setSubscriptionPlan("");localStorage.removeItem("xart-stripe-session");localStorage.removeItem("xart-subscription-plan")}if(params.get("session_id"))history.replaceState({},"",location.pathname)}).catch(()=>{})},[]);
  const openArticle=item=>{try{const history=JSON.parse(localStorage.getItem("xart-recent-reading")||"[]"),id=item.id||item.n;localStorage.setItem("xart-recent-reading",JSON.stringify([{id},...history.filter(value=>String(value.id)!==String(id))].slice(0,20)))}catch{}setOpen(item)};
  const login=()=>location.replace("/auth.html?next=/");const logout=async()=>{try{localStorage.removeItem("xart-auth-complete");localStorage.removeItem("xart-stripe-session");localStorage.removeItem("xart-subscription-plan");Object.keys(localStorage).filter(key=>/^sb-.*-auth-token$/.test(key)).forEach(key=>localStorage.removeItem(key))}catch{}setAuthenticated(false);setSubscribed(false);setSubscriptionPlan("");setOpenArchive(null);try{const client=getAuthClient();if(client)await Promise.race([client.auth.signOut(),new Promise(resolve=>setTimeout(resolve,2500))])}catch{}location.replace("/auth.html?next=/")};
  const canOpenArchives=authenticated&&subscribed&&ARCHIVE_ACCESS_PLANS.has(subscriptionPlan);
  const openArchiveRequest=archive=>{if(!authenticated){login();return}if(!canOpenArchives){setOpenArchive(null);setTab("subscribe");return}setOpenArchive(archive)};
  const archiveLocked=()=>{if(!authenticated){login();return}setOpenArchive(null);setTab("subscribe")};
  useEffect(()=>{if(!canOpenArchives&&openArchive)setOpenArchive(null)},[canOpenArchives,openArchive]);
  let screen=open?<Reader item={open} lang={lang} setLang={setLang} back={()=>setOpen(null)} toSubscribe={()=>{setOpen(null);setTab("subscribe")}} subscribed={subscribed}/>:openArchive&&canOpenArchives?<ArtistArchiveReader archive={openArchive} lang={lang} back={()=>setOpenArchive(null)}/>:tab==="discover"?<Discover lang={lang} setLang={setLang} open={openArticle} items={items} archives={archives} openArchive={openArchiveRequest} canOpenArchives={canOpenArchives} onArchiveLocked={archiveLocked}/>:tab==="analysis"?<Analysis lang={lang} setLang={setLang}/>:tab==="community"?<Community lang={lang} setLang={setLang}/>:tab==="subscribe"?<Subscribe lang={lang} setLang={setLang} subscribed={subscribed} subscriptionPlan={subscriptionPlan} onSubscribed={()=>setSubscribed(true)}/>:tab==="mine"?<Mine lang={lang} setLang={setLang} subscribed={subscribed} onSubscribe={()=>setTab("subscribe")} onLibrary={()=>setTab("library")} authenticated={authenticated} onLogin={login} onLogout={logout}/>:<Profile lang={lang} setLang={setLang} subscribed={subscribed} items={items} onRead={openArticle}/>;
  const pageTitle=tab==="discover"?ui[lang].discover:tab==="archives"?ui[lang].archives:tab==="library"?(lang==="zh"?"图书馆":ui[lang].library):tab==="mine"?ui[lang].mine:tab==="analysis"?(lang==="zh"?"研究":lang==="fr"?"Recherche":"Research"):tab==="community"?(lang==="zh"?"社区":lang==="fr"?"Communauté":"Community"):ui[lang].subscribe;
  const archiveHeaderTitle=openArchive?.title||pageTitle;
  return <><style>{responsiveStyles}{`@media(min-width:700px){.xart-bottom-nav{display:none!important}.xart-screen{padding-bottom:0!important}.xart-discover-archives-grid{grid-template-columns:minmax(0,1.45fr) minmax(260px,.75fr)!important;gap:0 36px!important}.xart-discover-archives .xart-discover-archive-card.featured{grid-column:auto!important}.xart-discover-feed{grid-template-columns:minmax(0,1.2fr) minmax(300px,.8fr)!important;gap:0 36px!important;padding-inline:clamp(28px,5vw,72px)!important;padding-bottom:80px!important}.xart-discover-card.featured{grid-column:1/-1!important;grid-template-columns:minmax(420px,1.2fr) minmax(320px,.8fr)!important;padding-top:38px!important;padding-bottom:38px!important}.xart-discover-card:not(.featured){padding-block:28px!important}}`}</style><style>{`@media(min-width:700px){.xart-discover-archives-grid{grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:0 28px!important;align-items:stretch!important}.xart-discover-archives .xart-discover-archive-card,.xart-discover-archives .xart-discover-archive-card.featured{display:flex!important;flex-direction:column!important;align-self:stretch!important;min-height:100%!important;padding-top:30px!important;padding-bottom:30px!important}.xart-discover-archives .xart-discover-archive-card img{display:block!important;width:100%!important;aspect-ratio:4/3!important;height:auto!important;object-fit:cover!important;margin-bottom:18px!important}.xart-discover-archives .xart-discover-card-copy{display:flex!important;flex:1!important;flex-direction:column!important}.xart-discover-archives .xart-discover-card-copy .xart-editorial-tools{margin-top:auto!important}}`}</style><style>{`:root{}.swiss-reader.swiss-theme-night{--reader-bg:#11110f!important;--reader-fg:#efede6!important;--reader-muted:#aaa79f!important;--reader-line:#3b3934!important;--reader-accent:#ef5b52!important;background:#11110f!important;color:#efede6!important}.swiss-theme-night .swiss-reader-header,.swiss-theme-night .swiss-reader-toolbar,.swiss-theme-night .swiss-reader-scroll,.swiss-theme-night .swiss-reader-hero,.swiss-theme-night .swiss-ai-panel,.swiss-theme-night .swiss-audio-panel,.swiss-theme-night .swiss-note-panel{background:#11110f!important;color:#efede6!important}.swiss-theme-night .swiss-reader-body{color:#efede6!important}.swiss-theme-night .swiss-original-pdf object{background:#1a1916!important}.xart-discover-archives .xart-discover-archive-card .xart-discover-card-copy h2{font-size:clamp(20px,2.35vw,34px)!important;line-height:1.06!important;letter-spacing:-.045em!important}.xart-discover-archives .xart-discover-archive-card .xart-discover-card-copy p{font-size:clamp(11px,.9vw,13px)!important;line-height:1.55!important}`}</style><div className="xart-stage w-full flex items-center justify-center"><div className="xart-device" style={{overflow:"hidden",display:"flex",flexDirection:"column"}}>{!open&&(tab!=="discover"||openArchive)&&<PageHeader lang={lang} setLang={setLang} title={archiveHeaderTitle}/>}<div className="xart-screen" style={{flex:1,overflow:"hidden"}}>{screen}</div>{!open&&!openArchive&&<Tabs tab={tab} setTab={setTab} lang={lang}/>}</div></div>{showSplash&&<div className="xart-splash" role="status" aria-label="X-ART Lab 正在启动"><div className="xart-splash-lockup"><span className="xart-splash-logo-shell"><span className="xart-splash-light" aria-hidden="true"/><svg className="xart-splash-logo" viewBox="0 0 500 500" role="img" aria-label="X-ART Lab"><path className="xart-splash-mark xart-splash-left" d="M105 90 L202 210 C226 237 226 263 202 290 L105 410"/><path className="xart-splash-mark xart-splash-right" d="M395 90 L298 210 C274 237 274 263 298 290 L395 410"/></svg></span><span className="xart-splash-caption">X-ART Lab.</span></div></div>}</>
}
